71	pub struct PrefillPagedPlan {
72	    inner: pegainfer_kernels::ops::PrefillPagedPlan,
73	}
74	
75	impl PrefillPagedPlan {
76	    pub fn new(
77	        ctx: &DeviceContext,
78	        desc: &KvDesc<'_>,
79	        start_pos: usize,
80	        seq_len: usize,
81	        num_q_heads: usize,
82	        num_kv_heads: usize,
83	        head_dim: usize,
84	    ) -> Result<Self> {
85	        Self::new_with_cta_tile_q(
86	            ctx,
87	            desc,
88	            start_pos,
89	            seq_len,
90	            num_q_heads,
91	            num_kv_heads,
92	            head_dim,
93	            0,
94	        )
95	    }
96	
97	    #[allow(clippy::too_many_arguments)]
98	    fn new_with_cta_tile_q(
99	        ctx: &DeviceContext,
100	        desc: &KvDesc<'_>,
101	        start_pos: usize,
102	        seq_len: usize,
103	        num_q_heads: usize,
104	        num_kv_heads: usize,
105	        head_dim: usize,
106	        cta_tile_q_override: i32,
107	    ) -> Result<Self> {
108	        let page_indices: Vec<i32> = desc
109	            .page_indices()
110	            .iter()
111	            .map(|p| p.index() as i32)
112	            .collect();
113	        Ok(Self {
114	            inner: pegainfer_kernels::ops::PrefillPagedPlan::new_with_cta_tile_q(
115	                ctx,
116	                &page_indices,
117	                desc.last_page_len(),
118	                start_pos,
119	                seq_len,
120	                num_q_heads,
121	                num_kv_heads,
122	                head_dim,
123	                cta_tile_q_override,
124	            )?,
125	        })
126	    }
127	
128	    #[allow(clippy::too_many_arguments)]
129	    pub fn from_raw_batch_with_cta_tile_q(
130	        ctx: &DeviceContext,
131	        page_indices: &[Vec<i32>],
132	        last_page_lens: &[usize],
133	        start_positions: &[usize],
134	        seq_lens: &[usize],
135	        num_q_heads: usize,
136	        num_kv_heads: usize,
137	        head_dim: usize,
138	        cta_tile_q_override: i32,
139	    ) -> Result<Self> {
140	        Ok(Self {
141	            inner: pegainfer_kernels::ops::PrefillPagedPlan::new_batch_with_cta_tile_q(
142	                ctx,
143	                page_indices,
144	                last_page_lens,
145	                start_positions,
146	                seq_lens,
147	                num_q_heads,
148	                num_kv_heads,
149	                head_dim,
150	                cta_tile_q_override,
151	            )?,
152	        })
153	    }
154	
155	    /// Pre-allocate a worst-case-sized plan to be refilled in place by
156	    /// [`Self::update_batch_with_cta_tile_q`] (graph-stable buffer reuse).
157	    pub fn new_preallocated(
158	        ctx: &DeviceContext,
159	        max_total_tokens: usize,
160	        max_total_pages: usize,
161	        max_batch: usize,
162	        max_tiles: usize,
163	    ) -> Result<Self> {
164	        Ok(Self {
165	            inner: pegainfer_kernels::ops::PrefillPagedPlan::new_preallocated(
166	                ctx,
167	                max_total_tokens,
168	                max_total_pages,
169	                max_batch,
170	                max_tiles,
171	            )?,
172	        })
173	    }
174	
175	    /// Refill a pre-allocated plan in place (no allocation, pointers unchanged).
176	    #[allow(clippy::too_many_arguments)]
177	    pub fn update_batch_with_cta_tile_q(
178	        &mut self,
179	        ctx: &DeviceContext,
180	        page_indices: &[Vec<i32>],
181	        last_page_lens: &[usize],
182	        start_positions: &[usize],
183	        seq_lens: &[usize],
184	        num_q_heads: usize,
185	        num_kv_heads: usize,
186	        head_dim: usize,
187	        cta_tile_q_override: i32,
188	    ) -> Result<()> {
189	        self.inner.update_batch_with_cta_tile_q(
190	            ctx,
191	            page_indices,
192	            last_page_lens,
193	            start_positions,
194	            seq_lens,
195	            num_q_heads,
196	            num_kv_heads,
197	            head_dim,
198	            cta_tile_q_override,
199	        )
200	    }
201	
202	    pub fn page_indices_d(&self) -> &CudaSlice<i32> {
203	        self.inner.page_indices_d()
204	    }
205	    pub fn page_indptr_d(&self) -> &CudaSlice<i32> {
206	        self.inner.page_indptr_d()
207	    }
208	    pub fn last_page_len_d(&self) -> &CudaSlice<i32> {
209	        self.inner.last_page_len_d()
210	    }
211	    pub fn q_indptr_d(&self) -> &CudaSlice<i32> {
212	        self.inner.q_indptr_d()
213	    }
214	    pub fn request_indices_d(&self) -> &CudaSlice<i32> {
215	        self.inner.request_indices_d()
216	    }
