163	    #[allow(clippy::too_many_arguments)]
164	    pub fn with_storage(
165	        ctx: &DeviceContext,
166	        num_layers: usize,
167	        num_kv_heads: usize,
168	        head_dim: usize,
169	        page_size: usize,
170	        num_pages: usize,
171	        storage: KvStorage,
172	    ) -> Result<Self> {
173	        Self::with_storage_and_format(
174	            ctx,
175	            num_layers,
176	            num_kv_heads,
177	            head_dim,
178	            page_size,
179	            num_pages,
180	            storage,
181	            KvFormat::Split,
182	        )
