184	
185	    #[allow(clippy::too_many_arguments)]
186	    pub fn with_storage_and_format(
187	        ctx: &DeviceContext,
188	        num_layers: usize,
189	        num_kv_heads: usize,
190	        head_dim: usize,
191	        page_size: usize,
192	        num_pages: usize,
193	        storage: KvStorage,
194	        format: KvFormat,
195	    ) -> Result<Self> {
196	        let layout = KvLayout::with_storage_and_format(
197	            num_layers,
198	            num_kv_heads,
199	            head_dim,
200	            page_size,
201	            storage,
202	            format,
203	        )?;
204	        let total_elements = num_pages.checked_mul(layout.page_stride).ok_or_else(|| {
205	            anyhow::anyhow!(
206	                "KvPool geometry overflows: {num_pages} pages x {} elements per page",
207	                layout.page_stride
208	            )
209	        })?;
210	        // The allocator multiplies by the element size unchecked; answer
211	        // for the byte domain here, before it does.
212	        let total_bytes = total_elements
213	            .checked_mul(layout.storage.elem_bytes())
214	            .ok_or_else(|| {
215	                anyhow::anyhow!(
216	                    "KvPool geometry overflows the byte domain: {total_elements} elements"
217	                )
218	            })?;
219	        let backing_slots = total_bytes.div_ceil(std::mem::size_of::<bf16>());
220	
221	        let buffer: CudaSlice<bf16> = ctx
222	            .stream
223	            .alloc_zeros(backing_slots)
224	            .map_err(|e| anyhow::anyhow!("KvPool alloc failed: {e}"))?;
225	
226	        let pool = PagePool::new(num_pages);
227	        let padding_permit = pool
228	            .try_acquire_many(1)
229	            .expect("pool must have at least 1 page for padding");
230	
231	        Ok(Self {
232	            inner: Arc::new(KvPoolInner {
233	                pool,
234	                buffer,
235	                layout,
236	                padding_permit,
237	            }),
238	        })
239	    }
