359	    /// Ensure capacity for at least `token_count` tokens total.
360	    pub fn ensure_capacity(&mut self, token_count: usize) -> Result<()> {
361	        let needed = pages_needed(token_count, self.pool.inner.layout.page_size);
362	        let held = self.permit.len();
363	        if needed <= held {
364	            return Ok(());
365	        }
366	        let grow = needed - held;
367	        if !self.permit.try_grow(grow) {
368	            bail!(
369	                "KvState: out of pages (need {grow} more, {} available)",
370	                self.pool.available_pages()
371	            );
372	        }
373	        Ok(())
374	    }
