380	    /// The apply half of an atomic multi-pool admission. The reservation must
381	    /// come from this state's pool, which the permit merge enforces.
382	    pub fn commit_reservation(&mut self, reservation: KvReservation) {
383	        self.permit.absorb(reservation.permit);
384	    }
