452	    fn test_pool(page_size: usize, num_pages: usize) -> KvPool {
453	        let ctx = DeviceContext::new().expect("GPU required for kv_pool tests");
454	        // Tiny allocation: 1 layer, 1 head, dim=1 — just enough to exercise logic.
455	        KvPool::new(&ctx, 1, 1, 1, page_size, num_pages).expect("KvPool::new failed")
456	    }
