473	    #[test]
474	    fn stride_geometry_qwen35() {
475	        // Qwen3.5-4B: 8 full attn layers, 4 KV heads, head_dim=256, page_size=16
476	        let l = KvLayout::new(8, 4, 256, 16).expect("layout");
477	
478	        assert_eq!(l.kv_block_len, 16 * 4 * 256); // 16384 elements
479	        assert_eq!(l.layer_stride, 2 * 16384); // 32768 (K + V)
480	        assert_eq!(l.page_stride, 8 * 32768); // 262144 per page
481	        // bytes: 262144 * 2 = 524288 = 512 KB per page
482	        assert_eq!(l.page_stride * 2, 512 * 1024);
483	    }
