487	        // Qwen3-4B: 36 full attn layers, 4 KV heads, head_dim=128, page_size=16
488	        let l = KvLayout::new(36, 4, 128, 16).expect("layout");
489	
490	        // 36 layers × 16384 = 589824 elements per page
491	        assert_eq!(l.page_stride, 589_824);
492	        // bytes: ~1.125 MB per page
493	    }
