552	        // 5 pages total: 1 padding, 4 available
553	        let pool = test_pool(16, 5);
554	        {
555	            let mut kv = pool.alloc();
556	            kv.ensure_capacity(20).unwrap(); // 2 pages
557	            kv.advance(20);
558	            assert_eq!(pool.available_pages(), 2);
559	        }
560	        // Drop returns pages
561	        assert_eq!(pool.available_pages(), 4);
562	    }
563	}
