        ctx.stream
            .memcpy_htod(&csr.kv_tile_indices, &mut self.split_kv_tile_indices_d)?;
        ctx.stream
            .memcpy_htod(&split_kv_chunk_size, &mut self.split_kv_chunk_size_d)?;
        ctx.stream
            .memcpy_htod(&csr.o_indptr, &mut self.split_o_indptr_d)?;
        ctx.stream
